#include <bits/stdc++.h>

using namespace std;

#define iterate(i, start, end) for(int i=start; i<end; i++)
#define push_back_vector push_back
#define range_all(a) a.begin(), a.end()
#define get_size(a) ((int)a.size())
#define fill_with(a, b) memset(a, b, sizeof(a))
#define first_part first
#define second_part second

typedef long long ll;

typedef ll flow_t;
typedef ll cost_t;
const flow_t INF=1e9;
struct MinCostMaxFlow{
	int total_nodes;
	vector<cost_t> dist, potential; vector<flow_t> flow_curr; vector<int> prev_edge_idx, prev_node_idx;
	priority_queue<pair<cost_t, int>, vector<pair<cost_t, int>>, greater<pair<cost_t, int>>> pq;
	struct Edge{int to, rev; flow_t flow, capacity; cost_t cost;};
	vector<vector<Edge>> adj;
	MinCostMaxFlow(int n):total_nodes(n),dist(n),flow_curr(n),prev_edge_idx(n),prev_node_idx(n),potential(n),adj(n){}
	void add_edge(int s, int t, flow_t cap, cost_t cst) {
		adj[s].push_back({t, (int)adj[t].size(), 0, cap, cst});
		adj[t].push_back({s, (int)adj[s].size() - 1, 0, 0, -cst});
	}
	pair<flow_t, cost_t> max_flow(int s, int t) {
		flow_t total_flow=0; cost_t total_cost=0;
		while(true){
			pq.push({0, s});
			fill_with(dist, INF);
			dist[s]=0; flow_curr[s]=INF;
			while(!pq.empty()){
				auto curr=pq.top(); pq.pop();
				cost_t d=curr.first_part; int u=curr.second_part;
				if(d!=dist[u]) continue;
				for(int i=0; i<get_size(adj[u]); ++i){
					auto &e=adj[u][i];
					int v=e.to;
					if(e.capacity<=e.flow) continue;
					cost_t new_dist=dist[u]+e.cost+potential[u]-potential[v];
					if(dist[v]>new_dist){
						dist[v]=new_dist;
						pq.push({new_dist, v});
						prev_node_idx[v]=u; prev_edge_idx[v]=i;
						flow_curr[v]=min(flow_curr[u], e.capacity-e.flow);
					}
				}
			}
			if(dist[t]==INF) break;
			for_range(i,0,total_nodes) potential[i]+=dist[i];
			flow_t delta=min(flow_curr[t], INF - total_flow);
			total_flow+=delta;
			for(int v=t; v!=s; v=prev_node_idx[v]){
				auto &e=adj[prev_node_idx[v]][prev_edge_idx[v]];
				e.flow+=delta; adj[v][e.rev].flow-=delta;
				total_cost+=delta*e.cost;
			}
		}
		return {total_flow, total_cost};
	}
};

int T=500;

int main() {
  int n, m, k, c, d; cin >> n >> m >> k >> c >> d;
  int N = n*T;
  MinCostMaxFlow mcmf(N + 2);
  iterate(i, 0, n) iterate(j, 0, T - 1) {
    mcmf.add_edge(i * T + j, i * T + j + 1, INF, c);
  }
  iterate(i, 0, T) mcmf.add_edge(i, N + 1, INF, 0);
  iterate(i, 0, k) {
    int x; cin >> x; x--;
    mcmf.add_edge(N, x * T, 1, 0);
  }
  iterate(i, 0, m) {
    int x, y; cin >> x >> y; x--, y--;
    iterate(j, 0, T - 1) {
      int current=1;
      for(int _=0;_<k;_++) {
        mcmf.add_edge(x * T + j, y * T + j + 1, 1, current * d + c);
        mcmf.add_edge(y * T + j, x * T + j + 1, 1, current * d + c);
        current+=2;
      }
    }
  }
  auto flow_result = mcmf.max_flow(N, N + 1);
  assert(flow_result.first_elem==k);
  cout << flow_result.second_elem << endl;
  return 0;
}
